    return emojis[x] || &#039;💰&#039;;
}

function renderData(data) {
    ctx.font = `${size}px Arial`;
    ctx.textAlign = &#039;center&#039;;
    ctx.textBaseline = &#039;middle&#039;;

    data.forEach((row, j) =&gt; {
        row.forEach((col, i) =&gt; {
